import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = path.dirname(fileURLToPath(import.meta.url))
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.png'))
const map = {}
for (const f of files) {
  const b64 = fs.readFileSync(path.join(dir, f)).toString('base64')
  map[f] = 'data:image/png;base64,' + b64
}
const out =
  '// AUTO-GENERATED by genSprites.mjs — 鲸鱼娘 28 帧精灵 base64 内联（CJS/ESM 双形态，单文件可直接引用，无需外部资源）\n' +
  '// 重新生成：node assets/deepseek/genSprites.mjs\n' +
  'var SPRITES = ' + JSON.stringify(map) + '\n' +
  'function spriteOf(stage, state) {\n' +
  "  var names = [stage + '-' + state, 'baby-' + state, stage + '-normal', 'baby-normal']\n" +
  '  for (var i = 0; i < names.length; i++) { if (SPRITES[names[i] + ".png"]) return SPRITES[names[i] + ".png"] }\n' +
  '  return ""\n' +
  '}\n' +
  'if (typeof module !== "undefined" && module.exports) { module.exports = { SPRITES: SPRITES, spriteOf: spriteOf } }\n' +
  'if (typeof export_default !== "undefined") { export_default({ SPRITES: SPRITES, spriteOf: spriteOf }) }\n'
fs.writeFileSync(path.join(dir, 'deepseekSprites.cjs'), out)
console.log('Generated deepseekSprites.cjs with', files.length, 'frames')
